sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	var fullName = current.u_nome_solicitante ? String(current.u_nome_solicitante).trim() : '';
	var rawCpf = current.u_cpf_solicitante ? String(current.u_cpf_solicitante) : '';
	var consumerSysId = '';

	if (!fullName || !rawCpf) {
		gs.warn('Business Rule: EV – Criar/vincular Consumer do solicitante:  Processo abortado.');
		return;
	}

	var cpf = rawCpf.replace(/\D/g, '');

	var grConsumer = new GlideRecord('csm_consumer');
	grConsumer.addQuery('u_cpf', cpf);
	grConsumer.setLimit(1);
	grConsumer.query();

	if (grConsumer.next()) {
		consumerSysId = grConsumer.getUniqueValue();
	} else {
		var nameParts = fullName.split(/\s+/);
		var firstName = nameParts[0];
		var middleName = '';
		var lastName = '';

		if (nameParts.length === 1) {
			lastName = '';
		} else if (nameParts.length === 2) {
			lastName = nameParts[1];
		} else {
			middleName = nameParts.slice(1, -1).join(' ');
			lastName = nameParts[nameParts.length - 1];
		}

		var consumerInsert = new GlideRecord('csm_consumer');
		consumerInsert.initialize();
		consumerInsert.first_name = firstName;
		consumerInsert.middle_name = middleName;
		consumerInsert.last_name = lastName;
		consumerInsert.u_cpf = cpf;
		consumerInsert.u_data_nascimento = current.u_data_nascimento_solicitante;
		consumerInsert.email = current.u_email_solicitante;
		consumerInsert.mobile_phone = current.u_telefone_solicitante;
		consumerInsert.active = true;
		consumerInsert.u_origem_cadastro = 'escola_virtual';

		consumerSysId = consumerInsert.insert();
	}

	if (consumerSysId && !current.u_consumer) {
		var updateCurrent = new GlideRecord(current.getTableName());
		if (updateCurrent.get(current.getUniqueValue())) {
			updateCurrent.u_consumer = consumerSysId;
			updateCurrent.update();
		}
	}

})(current, previous);
